package com.daniil.wristlens.wear;
import android.content.*;import android.net.Uri;import android.os.Handler;import android.os.Looper;import android.os.SystemClock;import androidx.annotation.NonNull;import androidx.work.*;import com.daniil.wristlens.shared.*;import com.daniil.wristlens.core.OriginalTransfer;import com.google.android.gms.tasks.Tasks;import com.google.android.gms.wearable.Wearable;import org.json.*;import java.io.IOException;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
/** Durable automatic copies use the same visible/cancellable state as manual downloads. */
public final class AutoSaveWorker extends Worker {
 private final Handler main=new Handler(Looper.getMainLooper());private volatile MediaClient client;private volatile String job="";
 public AutoSaveWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}
 private JSONObject request(JSONObject j)throws Exception{CompletableFuture<JSONObject> f=new CompletableFuture<>();main.post(()->client.request(j,f::complete,e->f.completeExceptionally(new IOException(e))));return f.get(20,TimeUnit.SECONDS);}
 @NonNull @Override public Result doWork(){Context c=getApplicationContext();SharedPreferences p=AutoSave.prefs(c);if(!AutoSave.enabled(c))return Result.success();String node=p.getString("node","");int copied=0;
  try{if(Tasks.await(Wearable.getNodeClient(c).getConnectedNodes(),10,TimeUnit.SECONDS).stream().noneMatch(n->n.isNearby()&&n.getId().equals(node)))throw new IOException(Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_06));client=new MediaClient(c,()->node,e->{});Tasks.await(Wearable.getMessageClient(c).addListener(client),10,TimeUnit.SECONDS);
   for(;;){if(isStopped()||!AutoSave.enabled(c))return Result.success();JSONArray items=request(Wire.object("op","sync","cursor",p.getLong("cursor",Long.MAX_VALUE))).getJSONArray("items");if(items.length()==0){if(copied>0)Controls.notice(c,String.format(Locale.getDefault(),Strings.tr(com.daniil.wristlens.shared.R.string.copy_downloaded_count),copied));p.edit().putString("status",p.getString("skipped","").isEmpty()?Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_07):p.getString("skipped","")).apply();return Result.success();}
    for(int i=0;i<items.length();i++){if(isStopped()||!AutoSave.enabled(c))return Result.success();JSONObject item=items.getJSONObject(i);String name=item.optString("name"),id=item.getString("id");if(item.optLong("bytes")<=0||item.optLong("bytes")>OriginalTransfer.MAX){if(!p.edit().putLong("cursor",Math.max(p.getLong("cursor",0),item.getLong("sequence"))).putString("skipped",name+": "+Strings.tr(com.daniil.wristlens.shared.R.string.wl_075)).commit())throw new IOException(Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_09));continue;}
     Downloads.State old=Downloads.state(c,node,id);if(old!=null&&old.active()){JSONObject j=Downloads.job(c,old.job());if(getId().toString().equals(j.optString("work")))Downloads.finish(c,old.job(),Downloads.ERROR);else{long until=SystemClock.elapsedRealtime()+TimeUnit.HOURS.toMillis(6);while((old=Downloads.state(c,node,id))!=null&&old.active()){if(isStopped()||!AutoSave.enabled(c))return Result.success();if(SystemClock.elapsedRealtime()>until)throw new IOException("Download queue timed out");new CountDownLatch(1).await(1,TimeUnit.SECONDS);}}}
     job=Downloads.create(c,node,List.of(item),true,getId());if(job.isEmpty())continue;String activeJob=job;Downloads.update(c,job,id,Downloads.PREPARING,0,0,name);setForegroundAsync(Downloads.foreground(c,job)).get(10,TimeUnit.SECONDS);if(copied==0)Controls.notice(c,Strings.tr(com.daniil.wristlens.shared.R.string.download_started));CompletableFuture<Uri> copy=new CompletableFuture<>();AtomicLong shown=new AtomicLong();
     main.post(()->client.fetchMeta(id,true,(n,total)->{Downloads.update(c,activeJob,id,Downloads.RUNNING,0,total,n);Downloads.notify(c,activeJob);},n->{long now=SystemClock.elapsedRealtime();if(now-shown.get()>500){shown.set(now);Downloads.update(c,activeJob,id,n<0?Downloads.PREPARING:Downloads.RUNNING,Math.max(0,n),0,null);Downloads.notify(c,activeJob);p.edit().putString("status",Downloads.label(Downloads.current(c,activeJob))).apply();}},copy::complete,e->copy.completeExceptionally(new IOException(e))));awaitCopy(copy);Downloads.update(c,job,id,Downloads.COMPLETE,0,0,null);Downloads.finish(c,job,Downloads.COMPLETE);copied++;if(!p.edit().putLong("cursor",Math.max(p.getLong("cursor",0),item.getLong("sequence"))).commit())throw new IOException(Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_09));job="";
    }
   }
  }catch(Exception e){if(isStopped()||!AutoSave.enabled(c)||!job.isEmpty()&&Downloads.cancelled(c,job))return Result.success();if(!job.isEmpty())Downloads.finish(c,job,Downloads.ERROR);Throwable cause=e.getCause()==null?e:e.getCause();p.edit().putString("status",cause.getMessage()==null?Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_10):cause.getMessage()).apply();return AutoSave.enabled(c)?Result.retry():Result.success();}finally{MediaClient old=client;if(old!=null)main.post(old::close);}
 }
 private Uri awaitCopy(CompletableFuture<Uri> f)throws Exception{long deadline=SystemClock.elapsedRealtime()+TimeUnit.HOURS.toMillis(6);for(;;){if(isStopped()||!AutoSave.enabled(getApplicationContext())||Downloads.cancelled(getApplicationContext(),job))throw new CancellationException();try{return f.get(1,TimeUnit.SECONDS);}catch(TimeoutException e){if(SystemClock.elapsedRealtime()>deadline)throw e;}}}
 @Override public void onStopped(){MediaClient old=client;if(old!=null)main.post(old::close);if(!job.isEmpty())Downloads.finish(getApplicationContext(),job,Downloads.ERROR);}
}
